// Fetches a JSON API (GET) and saves the response; optional bearer key from Hive › Keys by name.
const url = process.env.HIVE_INPUT_URL
const keyName = (process.env.HIVE_INPUT_KEY_NAME || '').trim()
const headers = { Accept: 'application/json' }
if (keyName) {
  const key = process.env[keyName]
  if (!key) throw new Error(`${keyName} is not set: add it in Hive › Keys`)
  headers.Authorization = `Bearer ${key}`
}
const res = await fetch(url, { headers })
if (!res.ok) throw new Error(`HTTP ${res.status} from ${url}`)
const body = await res.json()
const { writeFileSync } = await import('node:fs')
const out = `${process.env.ARTIFACTS_DIR}/response.json`
writeFileSync(out, JSON.stringify(body, null, 2))
console.log(`saved ${Array.isArray(body) ? body.length + ' items' : 'response'} -> ${out}`)
